sys_script_include.script:
var AccessGovernanceUtils = Class.create();
AccessGovernanceUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	getUserSecurityContext: function() {
        var userId = this.getParameter('sysparm_user_id');

        var result = {
            roles: [],
            groups: [],
            status: 'success'
        };

        if (!userId) {
            result.status = 'error';
            result.message = 'No User ID provided.';
            return JSON.stringify(result);
        }

        try {
            // 1. Fetch User Roles
            var roleGr = new GlideRecord('sys_user_has_role');
            roleGr.addQuery('user', userId);
            roleGr.addNotNullQuery('role');
            roleGr.query();

            while (roleGr.next()) {
                // Safe check to avoid null reference exceptions
                if (roleGr.role && roleGr.role.getDisplayValue()) {
                    var roleName = roleGr.role.name ? roleGr.role.name.toString() : roleGr.role.getDisplayValue();
                    if (result.roles.indexOf(roleName) === -1) {
                        result.roles.push(roleName);
                    }
                }
            }

            // 2. Fetch User Groups
            var groupGr = new GlideRecord('sys_user_grmember');
            groupGr.addQuery('user', userId);
            groupGr.addNotNullQuery('group');
            groupGr.query();

            while (groupGr.next()) {
                if (groupGr.group && groupGr.group.getDisplayValue()) {
                    var groupName = groupGr.group.name ? groupGr.group.name.toString() : groupGr.group.getDisplayValue();
                    if (result.groups.indexOf(groupName) === -1) {
                        result.groups.push(groupName);
                    }
                }
            }

        } catch (e) {
            result.status = 'error';
            result.message = 'Server Script Error: ' + e.message;
        }

        return JSON.stringify(result);
    },
    type: 'AccessGovernanceUtils'
});
